function* countUp() {
  let n = 1;
  while (true) yield n++;
}

const it = countUp()
  .filter((n) => n % 3 === 0)
  .map((n) => n + 1);

console.log(it.next().value);
console.log(it.next().value);
console.log(it.take(2).toArray().join(","));
const [a, b] = countUp().drop(3);
console.log(a + b);
